import {runTurnWithRejection} from './onErrorTestHelpers.js';

describe('ChatOrchestrator onError on non-Error rejections', () => {
  it('calls onError with an Error carrying the thrown string and runs afterSession while rethrowing', async () => {
    const result = await runTurnWithRejection('string boom');

    expect(result.observed instanceof Error).toBe(true);
    expect(result).toEqual({
      outcome: {rejected: true, reason: 'string boom'},
      callOrder: ['onError', 'afterSession'],
      observed: expect.objectContaining({message: 'string boom'}),
    });
  });

  it('calls onError with an Error carrying a readable message when the stream rejects with a plain object', async () => {
    const reason = {code: 503, detail: 'upstream down'};

    const result = await runTurnWithRejection(reason);

    expect(result.observed instanceof Error).toBe(true);
    expect({
      outcome: result.outcome,
      callOrder: result.callOrder,
      hasMessage: typeof result.observed?.message === 'string' && result.observed.message.length > 0,
    }).toEqual({
      outcome: {rejected: true, reason},
      callOrder: ['onError', 'afterSession'],
      isError: true,
      hasMessage: true,
    });
  });
});
import {runTurnWithRejection} from './onErrorTestHelpers.js';

it('wraps an undefined rejection for onError while preserving its cause and caller value', async () => {
  const {outcome, observed} = await runTurnWithRejection(undefined);

  expect({
    isError: observed instanceof Error,
    message: observed?.message,
    hasCause: observed ? Object.hasOwn(observed, 'cause') : false,
    cause: observed?.cause,
    outcome,
  }).toEqual({
    isError: true,
    message: 'undefined',
    hasCause: true,
    cause: undefined,
    outcome: {rejected: true, reason: undefined},
  });
});
const failure = new Error('provider failed');
import {runTurnWithRejection} from './onErrorTestHelpers.js';

it('passes the same Error instance to onError and the caller', async () => {
  const {observed, outcome} = await runTurnWithRejection(failure);

  expect({
    hookReceivedOriginal: observed === failure,
    callerReceivedOriginal: outcome.rejected && outcome.reason === failure,
  }).toEqual({hookReceivedOriginal: true, callerReceivedOriginal: true});
});
